import CryptoKit
import XCTest

@testable import KeepKit

/// `Fixtures/vectors.json` is a copy of `envisioning/keep`
/// `packages/crypto/src/vectors.json`, generated by the TypeScript
/// implementation. Everything in it must open here with the keys given.
/// Regenerate there, copy here, commit both.
final class KeepCryptoTests: XCTestCase {
  struct Vectors: Decodable {
    struct Key: Decodable { let publicKey: String; let privateKeyPkcs8: String }
    struct Vault: Decodable { let id: String; let key: String; let keyVersion: Int; let wrappedToRecipient: KeepWrappedKey }
    struct Item: Decodable { let id: String; let body: KeepItemBody; let sealed: KeepSealed }
    struct Passphrase: Decodable { let value: String; let wrapped: KeepSealed; let wrap: KeepWrapParams }
    struct PRF: Decodable { let output: String; let wrapped: KeepSealed; let wrap: KeepWrapParams }
    let suite: String
    let staff: Key
    let recipient: Key
    let vault: Vault
    let item: Item
    let passphrase: Passphrase
    let prf: PRF
  }

  private func vectors() throws -> Vectors {
    let url = try XCTUnwrap(Bundle.module.url(forResource: "vectors", withExtension: "json", subdirectory: "Fixtures"))
    return try KeepCoding.decoder.decode(Vectors.self, from: Data(contentsOf: url))
  }

  func testOpensItemSealedByTypeScript() throws {
    let v = try vectors()
    XCTAssertEqual(v.suite, KeepSuite.current)
    let key = try KeepCrypto.vaultKey(try KeepCrypto.data(base64URL: v.vault.key))
    let body = try KeepCrypto.openItem(v.item.sealed, vaultKey: key, vaultId: v.vault.id, itemId: v.item.id, keyVersion: v.vault.keyVersion)
    XCTAssertEqual(body, v.item.body)
    XCTAssertThrowsError(try KeepCrypto.openItem(v.item.sealed, vaultKey: key, vaultId: v.vault.id, itemId: v.item.id, keyVersion: v.vault.keyVersion + 1))
  }

  func testUnwrapsVaultKeyWrappedByTypeScript() throws {
    let v = try vectors()
    let recipient = try KeepCrypto.importPrivateKey(pkcs8: try KeepCrypto.data(base64URL: v.recipient.privateKeyPkcs8))
    let key = try KeepCrypto.unwrapKey(v.vault.wrappedToRecipient, privateKey: recipient, ownPublicKey: v.recipient.publicKey)
    XCTAssertEqual(KeepCrypto.base64URL(key), v.vault.key)
    // Re-addressed to the staff key: AAD mismatch.
    XCTAssertThrowsError(try KeepCrypto.unwrapKey(v.vault.wrappedToRecipient, privateKey: recipient, ownPublicKey: v.staff.publicKey))
  }

  func testUnwrapsPrivateKeyWrappedByPassphrase() throws {
    let v = try vectors()
    guard case .passphrase(let salt, let iterations) = v.passphrase.wrap else { return XCTFail("wrong wrap") }
    let wrappingKey = try KeepCrypto.wrappingKey(passphrase: v.passphrase.value, salt: try KeepCrypto.data(base64URL: salt), iterations: iterations)
    let restored = try KeepCrypto.unwrapPrivateKey(v.passphrase.wrapped, wrappingKey: wrappingKey)
    XCTAssertEqual(KeepCrypto.base64URL(restored.publicKey.x963Representation), v.staff.publicKey)
    let wrong = try KeepCrypto.wrappingKey(passphrase: "not it", salt: try KeepCrypto.data(base64URL: salt), iterations: iterations)
    XCTAssertThrowsError(try KeepCrypto.unwrapPrivateKey(v.passphrase.wrapped, wrappingKey: wrong))
  }

  func testUnwrapsPrivateKeyWrappedByPRF() throws {
    let v = try vectors()
    guard case .prf(_, let hkdfSalt) = v.prf.wrap else { return XCTFail("wrong wrap") }
    let wrappingKey = KeepCrypto.wrappingKey(prfOutput: try KeepCrypto.data(base64URL: v.prf.output), hkdfSalt: try KeepCrypto.data(base64URL: hkdfSalt))
    let restored = try KeepCrypto.unwrapPrivateKey(v.prf.wrapped, wrappingKey: wrappingKey)
    XCTAssertEqual(KeepCrypto.base64URL(restored.publicKey.x963Representation), v.staff.publicKey)
  }

  /// What this side seals, the other side must be able to open, so the
  /// exported private key has to be PKCS#8 (what WebCrypto imports), not
  /// SEC1. The prefix is the PKCS#8 envelope for a P-256 key.
  func testExportsPKCS8() throws {
    let pair = KeepCrypto.generateStaffKeypair()
    let der = KeepCrypto.exportPrivateKey(pair.privateKey)
    XCTAssertEqual(Array(der.prefix(10)), [0x30, 0x81, 0x87, 0x02, 0x01, 0x00, 0x30, 0x13, 0x06, 0x07])
    let reimported = try KeepCrypto.importPrivateKey(pkcs8: der)
    XCTAssertEqual(KeepCrypto.base64URL(reimported.publicKey.x963Representation), pair.publicKey)
  }

  func testRoundTripsEverythingItSeals() throws {
    let alice = KeepCrypto.generateStaffKeypair()
    let vaultKeyBytes = KeepCrypto.generateVaultKey()
    let wrapped = try KeepCrypto.wrapKey(vaultKeyBytes, toPublicKey: alice.publicKey)
    XCTAssertEqual(try KeepCrypto.unwrapKey(wrapped, privateKey: alice.privateKey, ownPublicKey: alice.publicKey), vaultKeyBytes)

    let key = try KeepCrypto.vaultKey(vaultKeyBytes)
    let body = KeepItemBody(username: "u", password: "p", url: "https://x", notes: "n", totp: "")
    let sealed = try KeepCrypto.sealItem(body, vaultKey: key, vaultId: "v", itemId: "i", keyVersion: 1)
    XCTAssertEqual(try KeepCrypto.openItem(sealed, vaultKey: key, vaultId: "v", itemId: "i", keyVersion: 1), body)
    XCTAssertThrowsError(try KeepCrypto.openItem(sealed, vaultKey: key, vaultId: "w", itemId: "i", keyVersion: 1))

    let (wrappedKey, wrap) = try KeepCrypto.wrapPrivateKey(alice.privateKey, passphrase: "correct horse battery staple")
    guard case .passphrase(let salt, let iterations) = wrap else { return XCTFail("wrong wrap") }
    let wrappingKey = try KeepCrypto.wrappingKey(passphrase: "correct horse battery staple", salt: try KeepCrypto.data(base64URL: salt), iterations: iterations)
    XCTAssertEqual(
      KeepCrypto.base64URL(try KeepCrypto.unwrapPrivateKey(wrappedKey, wrappingKey: wrappingKey).publicKey.x963Representation),
      alice.publicKey)
  }

  func testWireShapesMatchTheContract() throws {
    let wrap = KeepWrapParams.prf(credentialId: "c", hkdfSalt: "s")
    let json = try XCTUnwrap(String(data: try KeepCoding.encoder.encode(wrap), encoding: .utf8))
    XCTAssertTrue(json.contains("\"method\":\"prf\""))
    XCTAssertTrue(json.contains("\"credential_id\":\"c\""))
    XCTAssertTrue(json.contains("\"hkdf_salt\":\"s\""))
    let input = KeepCreateVaultInput(name: "A", projectId: nil, members: [], recoveryWrappedKey: nil)
    let created = try XCTUnwrap(String(data: try KeepCoding.encoder.encode(input), encoding: .utf8))
    XCTAssertTrue(created.contains("\"recovery_wrapped_key\":null"), created)
    XCTAssertTrue(created.contains("\"project_id\":null"), created)
  }
}

/// Shares must round-trip, and match the web's `keep-recovery-A:…` format
/// so a share written down from either client opens on the other.
final class KeepRecoveryShareTests: XCTestCase {
  func testSplitJoinAndFormat() throws {
    let pair = KeepCrypto.generateStaffKeypair()
    let secret = KeepCrypto.exportPrivateKey(pair.privateKey)
    let (a, b) = KeepCrypto.splitSecret(secret)
    XCTAssertEqual(try KeepCrypto.joinShares(a, b), secret)
    XCTAssertNotEqual(try KeepCrypto.joinShares(a, a), secret)
    let textA = KeepCrypto.formatShare("A", a)
    let textB = KeepCrypto.formatShare("B", b)
    XCTAssertTrue(textA.hasPrefix("keep-recovery-A:"))
    let parsedA = try KeepCrypto.parseShare(" \(textA)\n")
    let parsedB = try KeepCrypto.parseShare(textB)
    let joined = try KeepCrypto.joinShares(parsedA.share, parsedB.share)
    let restored = try KeepCrypto.importPrivateKey(pkcs8: joined)
    XCTAssertEqual(KeepCrypto.base64URL(restored.publicKey.x963Representation), pair.publicKey)
    XCTAssertThrowsError(try KeepCrypto.parseShare("keep-recovery-C:AAAA"))
    XCTAssertThrowsError(try KeepCrypto.parseShare("nope"))
  }
}
